#include <iostream> #include <random> // For random number generation #include <chrono> // For seeding with current time  int main() {     // Define the range for the random number     int min_value = 1;     int max_value = 100;      // Create a random number engine and seed it     // using the current time for better randomness     std::mt19937_64 rng(std::chrono::high_resolution_clock::now().time_since_epoch().count());      // Create a distribution to map the random numbers to the desired range     std::uniform_int_distribution<int> dist(min_value, max_value);      // Generate a random number     int random_number = dist(rng);      // Print the generated random number     std::cout << "Random number between " << min_value << " and " << max_value << ": " << random_number << std::endl;      return 0; }